  ) VALUES (
    '92a455ec-e9f6-406c-8fec-3d75ea79a4a2'::uuid,
    '3430f26e-9398-41bc-812d-464ed2570af8'::uuid,
    (SELECT cv.id FROM public.curriculum_versions cv JOIN public.subjects s ON s.id = cv.subject_id WHERE s.code = 'SSC-CHEM' AND cv.language_tag = 'bn' AND cv.edition_year = 2026 LIMIT 1),
    '## এ অধ্যায় পাঠ শেষে আমরা—

* রসায়নের ধারণা ব্যাখ্যা করতে পারব।
* রসায়নের ক্ষেত্রসমূহ চিহ্নিত করতে পারব।
* রসায়নের সাথে বিজ্ঞানের অন্য শাখাগুলোর সম্পর্ক ব্যাখ্যা করতে পারব।
* রসায়ন পাঠের গুরুত্ব ব্যাখ্যা করতে পারব।
* রসায়নে অনুসন্ধান ও গবেষণা প্রক্রিয়ার বর্ণনা করতে পারব।
* বিভিন্ন ধরনের অনুসন্ধানমূলক কাজের পরিকল্পনা প্রণয়ন, অনুমিত সিদ্ধান্ত গঠন ও পরীক্ষা করতে পারব।
* রসায়ন পরীক্ষাগারে কাজের সময় প্রয়োজনীয় সতর্কতা অবলম্বন করতে পারব।
* প্রকৃতিক ও বাস্তব জীবনের ঘটনাবলি রসায়নের দৃষ্টিতে ব্যাখ্যা করতে পারব।',
