    (SELECT cv.id FROM public.curriculum_versions cv JOIN public.subjects s ON s.id = cv.subject_id WHERE s.code = 'SSC-CHEM' AND cv.language_tag = 'bn' AND cv.edition_year = 2026 LIMIT 1),
    '## 1.1 রসায়ন পরিচিতি (Introduction to Chemistry)

প্রাগৈতিহাসিক যুগে মানুষ কাপড় পরতে জানত না, ঘরবাড়ি বানাতে জানত না, এমন কি রান্না করে খেতে জানত না। আজ ডিজিটালাইজেশনের যুগে মানুষ কত কিনা করছে। তাপকে নিয়ন্ত্রণ করে বিভিন্ন কাজে ব্যবহার করছে, বিদ্যুৎ উৎপাদন করতে শিখছে। বিদ্যুৎকে ব্যবহার করে মানুষ কত কী করছে। ইন্টারনেট ব্যবহার করে মানুষ ঘরে বসে পৃথিবীর কোথায় কী ঘটছে তা দেখতে পাচ্ছে। এগুলোর সব কিছুই হলো বিজ্ঞানের অবদান। সুতরাং স্বাভাবিকভাবেই প্রশ্ন হয়, বিজ্ঞান কী? বিজ্ঞান হলো, মানবজাতির পদ্ধতিগত, নিয়মানুগ ধারাবাহিক প্রচেষ্টা যার দ্বারা প্রকৃতিকে নিয়ন্ত্রণ করে নিজেদের কল্যাণে কাজে লাগানো। বিজ্ঞানের অনেকগুলো শাখা আছে যার মধ্যে রসায়ন হলো অন্যতম প্রধান শাখা। [প্রশ্ন: বিজ্ঞানের বিভিন্ন শাখার নাম লিখ।]

এখানে প্রশ্ন হলো, রসায়ন কী? বিজ্ঞানের যে শাখায় মৌল বা মৌলিক পদার্থের সমন্বয়ে গঠিত যৌগ বা যৌগিক পদার্থের সংযুক্তি, গঠন প্রকৃতি, ধর্ম, ব্যবহার ইত্যাদি এবং বস্তুসমূহের পারস্পরিক রূপান্তর ও রূপান্তরকালে শক্তি মূলত তাপ শক্তির শোষণ ও নিঃসরণ আলোচনা করা হয় তাকে রসায়ন বলে।',
    'markdown',
    '8',
    2,
    'theory',
    NULL,
    '1.1',
    'রসায়ন পরিচিতি (Introduction to Chemistry)'
