    '3430f26e-9398-41bc-812d-464ed2570af8'::uuid,
    (SELECT cv.id FROM public.curriculum_versions cv JOIN public.subjects s ON s.id = cv.subject_id WHERE s.code = 'SSC-CHEM' AND cv.language_tag = 'bn' AND cv.edition_year = 2026 LIMIT 1),
    'আমরা জানি, কয়লা পোড়ালে তাপ উৎপাদিত হয় সেই সাথে কার্বন ডাইঅক্সাইড যৌগ গঠিত হয়। আর্দ্র-পরিবেশে লোহা বা লোহা নির্মিত জিনিস রেখে দিলে তাতে মরিচা পড়ে, বিভিন্ন গাছের নির্যাস থেকে ঔষধ ও সুগন্ধি নিষ্কাশন করা হয়, আকরিক থেকে বিভিন্ন ধাতু নিষ্কাশন ইত্যাদি হলো রসায়নের কতিপয় উদাহরণ। বলা যায়, প্রাগৈতিহাসিক যুগ থেকেই মানুষ জেনে অথবা না জেনে বিভিন্নভাবে রসায়নের ব্যবহার করে আসছে। এ পর্যন্ত পাওয়া তথ্য অনুযায়ী প্রথম ব্যবহৃত ধাতু হলো তামা। এছাড়া সেই প্রাচীনকাল থেকেই মানুষ সোনা, রূপা, টিন, লোহা ইত্যাদি ধাতু ব্যবহার করছে।',
    'markdown',
    '8',
    3,
    'worked_example',
    NULL,
    '1.1',
    'রসায়ন পরিচিতি (Introduction to Chemistry)'
  )
